    def scale_row(i, c):
        augmented_matrix[i] = [c * x for x in augmented_matrix[i]]

    def add_multiple_of_row(i, j, c):
        augmented_matrix[j] = [a + b * c for a, b in zip(augmented_matrix[j], augmented_matrix[i])]

    pivot_row = 0
    for col in range(n):
        if pivot_row >= m:
            break

